(110110, 4813, 2928, '<td valign="top">Great shot, unusual idea, fits the challenge nicely.</td>', 'Great shot, unusual idea, fits the challenge nicely.', '2002-08-28 07:40:00.000000', NULL, 1),
(110111, 4813, 2204, '<td valign="top">Car photos don''t usually do to well with me but, this seems to be artistic and very well done.  I can''t really say why I like it, I just do.  =8 syamjonimi  ;''-D</td>', 'Car photos don''t usually do to well with me but, this seems to be artistic and very well done.  I can''t really say why I like it, I just do.  =8 syamjonimi  ;''-D', '2002-08-29 03:57:00.000000', NULL, 1),
