(111802, 4925, 2466, '<td valign="top">Hope you didn''t drop the camera! -ron</td>', 'Hope you didn''t drop the camera! -ron', '2002-08-26 21:10:00.000000', NULL, 1),
(111803, 4925, 2223, '<td valign="top">what is this?? a tire swing in motion?? im feeling a little sick.</td>', 'what is this?? a tire swing in motion?? im feeling a little sick.', '2002-08-26 21:28:00.000000', NULL, 1),
(111804, 4925, 1644, '<td valign="top">Getting sick just looking at it! Too bad the background couldn''t have been more colorful.</td>', 'Getting sick just looking at it! Too bad the background couldn''t have been more colorful.', '2002-08-26 21:39:00.000000', NULL, 1),
(111805, 4925, 1585, '<td valign="top">Barf!!!! But I like it. liltool</td>', 'Barf!!!! But I like it. liltool', '2002-08-27 02:46:00.000000', NULL, 1),
