(111857, 4928, 3087, '<td valign="top">Nice lines and lovely colours - good composition and no distracting background objects. Something about the gravel is making my eyes hurt and it''s too intrusive for me. <br/>6, Kavey</td>', 'Nice lines and lovely colours - good composition and no distracting background objects. Something about the gravel is making my eyes hurt and it''s too intrusive for me. 6, Kavey', '2002-08-28 12:05:00.000000', NULL, 1),
(111858, 4928, 3601, '<td valign="top">Good</td>', 'Good', '2002-08-28 17:09:00.000000', NULL, 1),
(111859, 4928, 1748, '<td valign="top">nice idea would a lower viewpoint have improved this image subjects a bit central</td>', 'nice idea would a lower viewpoint have improved this image subjects a bit central', '2002-08-28 19:08:00.000000', NULL, 1),
(111860, 4928, 1202, '<td valign="top">Composition: Subject Placement, Cropping, Background5,<br/>Technical: Focus, Exposure, Lighting, Processing6,<br/>Challenge: Does your entry meet it?7,<br/>Appeal: Is it Interesting, Motivating, Etc.? 4,<br/>Total Averaged Rating6.   Autool<br/></td>', 'Composition: Subject Placement, Cropping, Background5,Technical: Focus, Exposure, Lighting, Processing6,Challenge: Does your entry meet it?7,Appeal: Is it Interesting, Motivating, Etc.? 4,Total Averaged Rating6.   Autool', '2002-08-29 09:44:00.000000', NULL, 1),
